import{_ as r,o as g,c as l,a5 as e}from"./chunks/framework.DJo0M80U.js";const i=JSON.parse('{"title":"SpringBoot - 多模块项目的搭建教程","description":"","frontmatter":{"title":"SpringBoot - 多模块项目的搭建教程","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/A-入门/SpringBoot - 多模块项目的搭建教程.md","filePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/A-入门/SpringBoot - 多模块项目的搭建教程.md"}'),o={name:"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/A-入门/SpringBoot - 多模块项目的搭建教程.md"};function b(a,t,n,s,d,p){return g(),l("div",null,[...t[0]||(t[0]=[e('<div><p>注意：</p><ul><li>根为pom，其它为jar</li><li>web保留启动类，其它都可以删除启动类和配置文件</li><li>至少有base，dao，service，web四个模块</li><li>在根pom中parent为spring-boot-starter-parent，它的版本由本机jdk版本决定，而它又决定了其它spring模块的版本</li><li>根pom中还要声明所有modules，models中的还要在dependence中声明，运行clean和install都在根目录统一处理。根pom中声明的依赖，子模块要使用也要声明，但是可以不再给出版本号，如果不是pom中统一管理的依赖，要配置version。</li><li></li></ul><p><strong>Maven</strong> 多模块项目通常由一个父模块和若干个子模块构成，每个模块都对应着一个 <strong>pom.xml</strong>。它们之间通过继承和聚合（也称作多模块）相互关联。多模块适用于一些比较大的项目，通过合理的模块拆分，实现代码的复用，便于维护和管理。     本文通过构建一个包含 <strong>4</strong> 个子模块的项目，来演示 <strong>SpringBoot</strong> 在 <strong>Maven</strong> 环境的多模块构建过程。 <strong>1，创建父工程</strong> （1）首先，先创建一个 <strong>Spring Initializr</strong> 工程 <strong>hangge</strong> 作为 父工程（不添加任何依赖）：</p><p><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a></p><p>（2）删除刚创建工程里不需要的文件， 只保留：<strong>.idea</strong> 文件夹 、项目 <strong>pom</strong> 文件、以及一个 *<strong>.iml</strong> 文件。 <strong>注意</strong>： 因为父模块只做依赖管理，不需要编写代码，所以 <strong>src</strong> 文件夹可以直接删除。</p><p><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a></p><p>（3）删除后结果如下：</p><p><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a></p><p><strong>2，创建子模块</strong> （1）右键点击父工程，选择 <strong>New</strong> -&gt; <strong>Module...</strong> 创建子模块。这里依次创建 <strong>hangge-base</strong>、<strong>hangge-dao</strong>、<strong>hangge-service</strong> 和 <strong>hangge-web</strong> 共 <strong>4</strong> 个模块。 <strong>注意</strong>：除了 <strong>hangge-web</strong> 子模块创建时选择添加 <strong>Spring Web</strong> 依赖（当然也可以创建时不添加，等后面再手动编辑 <strong>pom.xml</strong> 文件添加），其他模块暂时不添加依赖。</p><p><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a></p><p>（2）将 <strong>4</strong> 个子模块的 <strong>mvnw</strong>、<strong>mvnw.cmd</strong> 文件及 <strong>.mvn</strong> 文件夹全部删除。</p><p><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a></p><p>（3）对于 <strong>src</strong> 里的内容，只保留 <strong>hangge-web</strong> 的启动类和配置文件，其他子模块的的启动类和配置文件都删除：</p><p><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a></p><p>（4）删除后结果如下：</p><p><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a></p><p><strong>3，编辑父工程 pom.xml 文件</strong>     将父工程 <strong>pom.xml</strong> 文件修改成如下内容，里面声明该父工程包含的子模块，同时抽取统一的配置信息和依赖版本控制，这样可以方便子 <strong>pom</strong> 直接引用，简化子 <strong>pom</strong> 的配置。</p><ul><li>多模块项目中，父模块打包类型必须是 <strong>pom</strong>。</li><li>因为开发框架是 <strong>spring boot</strong>，父模块默认继承 <strong>spring-boot-starter-parent</strong>，因此可以删除 <strong>spring-boot-starter</strong> 和 <strong>spring-boot-starter-test</strong> 依赖（祖先已经包含了）</li></ul><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;14&lt;br&gt;15&lt;br&gt;16&lt;br&gt;17&lt;br&gt;18&lt;br&gt;19&lt;br&gt;20&lt;br&gt;21&lt;br&gt;22&lt;br&gt;23&lt;br&gt;24&lt;br&gt;25&lt;br&gt;26&lt;br&gt;27&lt;br&gt;28&lt;br&gt;29&lt;br&gt;30&lt;br&gt;31&lt;br&gt;32&lt;br&gt;33&lt;br&gt;34&lt;br&gt;35&lt;br&gt;36&lt;br&gt;37&lt;br&gt;38&lt;br&gt;39&lt;br&gt;40&lt;br&gt;41&lt;br&gt;42&lt;br&gt;43&lt;br&gt;44&lt;br&gt;45&lt;br&gt;46&lt;br&gt;47&lt;br&gt;48&lt;br&gt;49&lt;br&gt;50&lt;br&gt;51&lt;br&gt;52&lt;br&gt;53&lt;br&gt;54&lt;br&gt;55&lt;br&gt;56&lt;br&gt;57&lt;br&gt;58&lt;br&gt;59&lt;br&gt;60&lt;br&gt;61&lt;br&gt;62&lt;br&gt;</code></td><td><code>&lt;br&gt;\\&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?\\&gt;&lt;br&gt;\\&lt;project xmlns=&quot; http://maven.apache.org/POM/4.0.0&quot;&lt;br&gt;         xmlns:xsi=&quot; http://www.w3.org/2001/XMLSchema-instance&quot;&lt;br&gt;         xsi:schemaLocation=&quot; http://maven.apache.org/POM/4.0.0&lt;br&gt;          https://maven.apache.org/xsd/maven-4.0.0.xsd&quot;\\&gt;&lt;br&gt;    \\&lt;modelVersion\\&gt;4.0.0\\&lt;/modelVersion\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;    \\&lt;artifactId\\&gt;hangge\\&lt;/artifactId\\&gt;&lt;br&gt;    \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;    \\&lt;name\\&gt;hangge\\&lt;/name\\&gt;&lt;br&gt;    \\&lt;description\\&gt;Demo project for Spring Boot\\&lt;/description\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;!-- &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;父模块打包类型必须为&lt;br&gt;&lt;br&gt;<code>&lt;br&gt;pom --\\&gt;&lt;br&gt;    \\&lt;packaging\\&gt;pom\\&lt;/packaging\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;!-- parent&lt;br&gt;</code>&lt;br&gt;&lt;br&gt;指明继承关系，给出被继承的父项目的具体信息&lt;br&gt;&lt;br&gt;<code>&lt;br&gt;--\\&gt;&lt;br&gt;    \\&lt;parent\\&gt;&lt;br&gt;        \\&lt;groupId\\&gt;org.springframework.boot\\&lt;/groupId\\&gt;&lt;br&gt;        \\&lt;artifactId\\&gt;spring-boot-starter-parent\\&lt;/artifactId\\&gt;&lt;br&gt;        \\&lt;version\\&gt;2.2.5.RELEASE\\&lt;/version\\&gt;&lt;br&gt;        \\&lt;relativePath/\\&gt; \\&lt;!-- lookup parent from repository --\\&gt;&lt;br&gt;    \\&lt;/parent\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;properties\\&gt;&lt;br&gt;        \\&lt;java.version\\&gt;1.8\\&lt;/java.version\\&gt;&lt;br&gt;    \\&lt;/properties\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;!-- &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;模块说明：这里声明多个子模块&lt;br&gt;&lt;br&gt;<code>&lt;br&gt; --\\&gt;&lt;br&gt;    \\&lt;modules\\&gt;&lt;br&gt;        \\&lt;module\\&gt;hangge-base\\&lt;/module\\&gt;&lt;br&gt;        \\&lt;module\\&gt;hangge-dao\\&lt;/module\\&gt;&lt;br&gt;        \\&lt;module\\&gt;hangge-service\\&lt;/module\\&gt;&lt;br&gt;        \\&lt;module\\&gt;hangge-web\\&lt;/module\\&gt;&lt;br&gt;    \\&lt;/modules\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;!-- &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;版本说明：这里统一管理依赖的版本号&lt;br&gt;&lt;br&gt;<code>&lt;br&gt; --\\&gt;&lt;br&gt;    \\&lt;dependencyManagement\\&gt;&lt;br&gt;        \\&lt;dependencies\\&gt;&lt;br&gt;            \\&lt;dependency\\&gt;&lt;br&gt;                \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;                \\&lt;artifactId\\&gt;hangge-base\\&lt;/artifactId\\&gt;&lt;br&gt;                \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;            \\&lt;/dependency\\&gt;&lt;br&gt;            \\&lt;dependency\\&gt;&lt;br&gt;                \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;                \\&lt;artifactId\\&gt;hangge-dao\\&lt;/artifactId\\&gt;&lt;br&gt;                \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;            \\&lt;/dependency\\&gt;&lt;br&gt;            \\&lt;dependency\\&gt;&lt;br&gt;                \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;                \\&lt;artifactId\\&gt;hangge-service\\&lt;/artifactId\\&gt;&lt;br&gt;                \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;            \\&lt;/dependency\\&gt;&lt;br&gt;            \\&lt;dependency\\&gt;&lt;br&gt;                \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;                \\&lt;artifactId\\&gt;hangge-web\\&lt;/artifactId\\&gt;&lt;br&gt;                \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;            \\&lt;/dependency\\&gt;&lt;br&gt;        \\&lt;/dependencies\\&gt;&lt;br&gt;    \\&lt;/dependencyManagement\\&gt;&lt;br&gt;\\&lt;/project\\&gt;&lt;br&gt;</code></td></tr></tbody></table><p><strong>4，编辑子模块 pom.xml 文件</strong> （1）子模块 <strong>hangge-base</strong> 的 <strong>pom.xml</strong> 文件内容如下，其中 <strong>parent</strong> 要使用顶层的父模块，同时由于我们项目用到了 <strong>Lombok</strong> ，所以还添加了 <strong>lombok</strong> 依赖： <strong>注意</strong>：由于子模块的配置信息会继承父模块的，所以子模块原来的 <strong>properties</strong> 可删掉。</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;14&lt;br&gt;15&lt;br&gt;16&lt;br&gt;17&lt;br&gt;18&lt;br&gt;19&lt;br&gt;20&lt;br&gt;21&lt;br&gt;22&lt;br&gt;23&lt;br&gt;24&lt;br&gt;25&lt;br&gt;26&lt;br&gt;27&lt;br&gt;28&lt;br&gt;</code></td><td><code>&lt;br&gt;\\&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?\\&gt;&lt;br&gt;\\&lt;project xmlns=&quot; http://maven.apache.org/POM/4.0.0&quot;&lt;br&gt;         xmlns:xsi=&quot; http://www.w3.org/2001/XMLSchema-instance&quot;&lt;br&gt;         xsi:schemaLocation=&quot; http://maven.apache.org/POM/4.0.0&lt;br&gt;          https://maven.apache.org/xsd/maven-4.0.0.xsd&quot;\\&gt;&lt;br&gt;    \\&lt;modelVersion\\&gt;4.0.0\\&lt;/modelVersion\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;    \\&lt;artifactId\\&gt;hangge-base\\&lt;/artifactId\\&gt;&lt;br&gt;    \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;    \\&lt;name\\&gt;hangge-base\\&lt;/name\\&gt;&lt;br&gt;    \\&lt;description\\&gt;Demo project for Spring Boot\\&lt;/description\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;!-- &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;继承本项目的父工程&lt;br&gt;&lt;br&gt;<code>&lt;br&gt; --\\&gt;&lt;br&gt;    \\&lt;parent\\&gt;&lt;br&gt;        \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;        \\&lt;artifactId\\&gt;hangge\\&lt;/artifactId\\&gt;&lt;br&gt;        \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;    \\&lt;/parent\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;dependencies\\&gt;&lt;br&gt;        \\&lt;dependency\\&gt;&lt;br&gt;            \\&lt;groupId\\&gt;org.projectlombok\\&lt;/groupId\\&gt;&lt;br&gt;            \\&lt;artifactId\\&gt;lombok\\&lt;/artifactId\\&gt;&lt;br&gt;            \\&lt;version\\&gt;1.18.6\\&lt;/version\\&gt;&lt;br&gt;        \\&lt;/dependency\\&gt;&lt;br&gt;    \\&lt;/dependencies\\&gt;&lt;br&gt;\\&lt;/project\\&gt;&lt;br&gt;</code></td></tr></tbody></table><p>（2）子模块 <strong>hangge-dao</strong> 的 <strong>pom.xml</strong> 文件内容如下，同样 <strong>parent</strong> 要使用顶层的父模块，并添加 <strong>hangge-base</strong> 子模块，以及数据库相关依赖：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;14&lt;br&gt;15&lt;br&gt;16&lt;br&gt;17&lt;br&gt;18&lt;br&gt;19&lt;br&gt;20&lt;br&gt;21&lt;br&gt;22&lt;br&gt;23&lt;br&gt;24&lt;br&gt;25&lt;br&gt;26&lt;br&gt;27&lt;br&gt;28&lt;br&gt;29&lt;br&gt;30&lt;br&gt;31&lt;br&gt;32&lt;br&gt;33&lt;br&gt;34&lt;br&gt;35&lt;br&gt;36&lt;br&gt;37&lt;br&gt;38&lt;br&gt;39&lt;br&gt;40&lt;br&gt;41&lt;br&gt;42&lt;br&gt;43&lt;br&gt;44&lt;br&gt;</code></td><td><code>&lt;br&gt;\\&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?\\&gt;&lt;br&gt;\\&lt;project xmlns=&quot; http://maven.apache.org/POM/4.0.0&quot;&lt;br&gt;         xmlns:xsi=&quot; http://www.w3.org/2001/XMLSchema-instance&quot;&lt;br&gt;         xsi:schemaLocation=&quot; http://maven.apache.org/POM/4.0.0&lt;br&gt;          https://maven.apache.org/xsd/maven-4.0.0.xsd&quot;\\&gt;&lt;br&gt;    \\&lt;modelVersion\\&gt;4.0.0\\&lt;/modelVersion\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;    \\&lt;artifactId\\&gt;hangge-dao\\&lt;/artifactId\\&gt;&lt;br&gt;    \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;    \\&lt;name\\&gt;hangge-dao\\&lt;/name\\&gt;&lt;br&gt;    \\&lt;description\\&gt;Demo project for Spring Boot\\&lt;/description\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;!-- &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;继承本项目的父工程&lt;br&gt;&lt;br&gt;<code>&lt;br&gt; --\\&gt;&lt;br&gt;    \\&lt;parent\\&gt;&lt;br&gt;        \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;        \\&lt;artifactId\\&gt;hangge\\&lt;/artifactId\\&gt;&lt;br&gt;        \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;    \\&lt;/parent\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;dependencies\\&gt;&lt;br&gt;        \\&lt;!-- dao &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;子模块又依赖 <code>base</code> 子模块&lt;br&gt;&lt;br&gt;<code>&lt;br&gt; --\\&gt;&lt;br&gt;        \\&lt;dependency\\&gt;&lt;br&gt;            \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;            \\&lt;artifactId\\&gt;hangge-base\\&lt;/artifactId\\&gt;&lt;br&gt;        \\&lt;/dependency\\&gt;&lt;br&gt;        \\&lt;!-- Spring Data JPA &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;依赖&lt;br&gt;&lt;br&gt;<code>&lt;br&gt; --\\&gt;&lt;br&gt;        \\&lt;dependency\\&gt;&lt;br&gt;            \\&lt;groupId\\&gt;org.springframework.boot\\&lt;/groupId\\&gt;&lt;br&gt;            \\&lt;artifactId\\&gt;spring-boot-starter-data-jpa\\&lt;/artifactId\\&gt;&lt;br&gt;        \\&lt;/dependency\\&gt;&lt;br&gt;        \\&lt;!-- &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;数据库驱动依赖&lt;br&gt;&lt;br&gt;<code>&lt;br&gt; --\\&gt;&lt;br&gt;        \\&lt;dependency\\&gt;&lt;br&gt;            \\&lt;groupId\\&gt;mysql\\&lt;/groupId\\&gt;&lt;br&gt;            \\&lt;artifactId\\&gt;mysql-connector-java\\&lt;/artifactId\\&gt;&lt;br&gt;        \\&lt;/dependency\\&gt;&lt;br&gt;        \\&lt;!-- &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;数据库连接池&lt;br&gt;&lt;br&gt;<code>&lt;br&gt; --\\&gt;&lt;br&gt;        \\&lt;dependency\\&gt;&lt;br&gt;            \\&lt;groupId\\&gt;com.alibaba\\&lt;/groupId\\&gt;&lt;br&gt;            \\&lt;artifactId\\&gt;druid\\&lt;/artifactId\\&gt;&lt;br&gt;            \\&lt;version\\&gt;1.1.9\\&lt;/version\\&gt;&lt;br&gt;        \\&lt;/dependency\\&gt;&lt;br&gt;    \\&lt;/dependencies\\&gt;&lt;br&gt;\\&lt;/project\\&gt;&lt;br&gt;</code></td></tr></tbody></table><p>（3）子模块 <strong>hangge-service</strong> 的 <strong>pom.xml</strong> 文件内容如下，同样 <strong>parent</strong> 要使用顶层的父模块，并添加 <strong>hangge-dao</strong> 子模块依赖：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;14&lt;br&gt;15&lt;br&gt;16&lt;br&gt;17&lt;br&gt;18&lt;br&gt;19&lt;br&gt;20&lt;br&gt;21&lt;br&gt;22&lt;br&gt;23&lt;br&gt;24&lt;br&gt;25&lt;br&gt;26&lt;br&gt;27&lt;br&gt;28&lt;br&gt;</code></td><td><code>&lt;br&gt;\\&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?\\&gt;&lt;br&gt;\\&lt;project xmlns=&quot; http://maven.apache.org/POM/4.0.0&quot;&lt;br&gt;         xmlns:xsi=&quot; http://www.w3.org/2001/XMLSchema-instance&quot;&lt;br&gt;         xsi:schemaLocation=&quot; http://maven.apache.org/POM/4.0.0&lt;br&gt;           https://maven.apache.org/xsd/maven-4.0.0.xsd&quot;\\&gt;&lt;br&gt;    \\&lt;modelVersion\\&gt;4.0.0\\&lt;/modelVersion\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;    \\&lt;artifactId\\&gt;hangge-service\\&lt;/artifactId\\&gt;&lt;br&gt;    \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;    \\&lt;name\\&gt;hangge-service\\&lt;/name\\&gt;&lt;br&gt;    \\&lt;description\\&gt;Demo project for Spring Boot\\&lt;/description\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;!-- &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;继承本项目的父工程&lt;br&gt;&lt;br&gt;<code>&lt;br&gt; --\\&gt;&lt;br&gt;    \\&lt;parent\\&gt;&lt;br&gt;        \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;        \\&lt;artifactId\\&gt;hangge\\&lt;/artifactId\\&gt;&lt;br&gt;        \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;    \\&lt;/parent\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;dependencies\\&gt;&lt;br&gt;        \\&lt;!-- service &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;子模块又依赖 <code>dao</code> 子模块&lt;br&gt;&lt;br&gt;<code>&lt;br&gt; --\\&gt;&lt;br&gt;        \\&lt;dependency\\&gt;&lt;br&gt;            \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;            \\&lt;artifactId\\&gt;hangge-dao\\&lt;/artifactId\\&gt;&lt;br&gt;        \\&lt;/dependency\\&gt;&lt;br&gt;    \\&lt;/dependencies\\&gt;&lt;br&gt;\\&lt;/project\\&gt;&lt;br&gt;</code></td></tr></tbody></table><p>（4）子模块 <strong>hangge-web</strong> 的 <strong>pom.xml</strong> 文件内容如下，同样 <strong>parent</strong> 要使用顶层的父模块，并添加 <strong>hangge-service</strong> 子模块依赖： <strong>注意</strong>： 之前创建这个子模块的时候已经添加了 <strong>spring-boot-starter-web</strong> 依赖，如果没有则手动添加。</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;14&lt;br&gt;15&lt;br&gt;16&lt;br&gt;17&lt;br&gt;18&lt;br&gt;19&lt;br&gt;20&lt;br&gt;21&lt;br&gt;22&lt;br&gt;23&lt;br&gt;24&lt;br&gt;25&lt;br&gt;26&lt;br&gt;27&lt;br&gt;28&lt;br&gt;29&lt;br&gt;30&lt;br&gt;31&lt;br&gt;32&lt;br&gt;33&lt;br&gt;34&lt;br&gt;35&lt;br&gt;36&lt;br&gt;37&lt;br&gt;38&lt;br&gt;39&lt;br&gt;40&lt;br&gt;41&lt;br&gt;42&lt;br&gt;</code></td><td><code>&lt;br&gt;\\&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?\\&gt;&lt;br&gt;\\&lt;project xmlns=&quot; http://maven.apache.org/POM/4.0.0&quot;&lt;br&gt;         xmlns:xsi=&quot; http://www.w3.org/2001/XMLSchema-instance&quot;&lt;br&gt;         xsi:schemaLocation=&quot; http://maven.apache.org/POM/4.0.0&lt;br&gt;          https://maven.apache.org/xsd/maven-4.0.0.xsd&quot;\\&gt;&lt;br&gt;    \\&lt;modelVersion\\&gt;4.0.0\\&lt;/modelVersion\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;    \\&lt;artifactId\\&gt;hangge-web\\&lt;/artifactId\\&gt;&lt;br&gt;    \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;    \\&lt;name\\&gt;hangge-web\\&lt;/name\\&gt;&lt;br&gt;    \\&lt;description\\&gt;Demo project for Spring Boot\\&lt;/description\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;!-- &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;继承本项目的父工程&lt;br&gt;&lt;br&gt;<code>&lt;br&gt; --\\&gt;&lt;br&gt;    \\&lt;parent\\&gt;&lt;br&gt;        \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;        \\&lt;artifactId\\&gt;hangge\\&lt;/artifactId\\&gt;&lt;br&gt;        \\&lt;version\\&gt;0.0.1-SNAPSHOT\\&lt;/version\\&gt;&lt;br&gt;    \\&lt;/parent\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;dependencies\\&gt;&lt;br&gt;        \\&lt;!-- web &lt;br&gt;</code>&lt;br&gt;&lt;br&gt;子模块又依赖 <code>service</code> 子模块&lt;br&gt;&lt;br&gt;<code>&lt;br&gt; --\\&gt;&lt;br&gt;        \\&lt;dependency\\&gt;&lt;br&gt;            \\&lt;groupId\\&gt;com.example\\&lt;/groupId\\&gt;&lt;br&gt;            \\&lt;artifactId\\&gt;hangge-service\\&lt;/artifactId\\&gt;&lt;br&gt;        \\&lt;/dependency\\&gt;&lt;br&gt; &lt;br&gt;        \\&lt;dependency\\&gt;&lt;br&gt;            \\&lt;groupId\\&gt;org.springframework.boot\\&lt;/groupId\\&gt;&lt;br&gt;            \\&lt;artifactId\\&gt;spring-boot-starter-web\\&lt;/artifactId\\&gt;&lt;br&gt;        \\&lt;/dependency\\&gt;&lt;br&gt;    \\&lt;/dependencies\\&gt;&lt;br&gt; &lt;br&gt;    \\&lt;build\\&gt;&lt;br&gt;        \\&lt;plugins\\&gt;&lt;br&gt;            \\&lt;plugin\\&gt;&lt;br&gt;                \\&lt;groupId\\&gt;org.springframework.boot\\&lt;/groupId\\&gt;&lt;br&gt;                \\&lt;artifactId\\&gt;spring-boot-maven-plugin\\&lt;/artifactId\\&gt;&lt;br&gt;            \\&lt;/plugin\\&gt;&lt;br&gt;        \\&lt;/plugins\\&gt;&lt;br&gt;    \\&lt;/build\\&gt;&lt;br&gt;\\&lt;/project\\&gt;&lt;br&gt;</code></td></tr></tbody></table><p><strong>5，移动项目启动类所在的包</strong> （1）目前项目启动类 <strong>HanggeWebApplication</strong> 在 <strong>com.example.hanggeweb</strong> 包下面，我们需要将其移动移动到 <strong>com.example</strong> 包下。     如果不移动启动类的话，在多模块项目中会可能会碰到一个模块无法通过 <strong>@Autowired</strong> 注入其他模块里的对象的问题。启动时会报类似如下的错误：</p><ul><li><strong>Field bookService in com.example.hanggeweb.controller.HelloController required a bean of type &#39;com.example.hanggeservice.BookService&#39; that could not be found.</strong></li></ul><p>（2）移动的方式就是右键点击 <strong>HanggeWebApplication</strong> 选择 <strong>Refactor</strong> -&gt; <strong>Move...</strong></p><p><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a></p><p>（3）在弹出框中将 <strong>To package</strong> 设置成 <strong>com.example</strong> 后点击 <strong>Refactor</strong> 按钮移动：</p><p><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a></p><p><strong>6，开始编码</strong> （1）首先在 <strong>hangge-dao</strong> 模块中添加一个 <strong>Book</strong> 实体类：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;</code></td><td><code>&lt;br&gt;@Entity(name = &quot;book&quot;)&lt;br&gt;@Setter&lt;br&gt;@Getter&lt;br&gt;@NoArgsConstructor&lt;br&gt;public class Book \\{&lt;br&gt;    @Id&lt;br&gt;    @GeneratedValue(strategy = GenerationType.IDENTITY)&lt;br&gt;    private Integer id;&lt;br&gt;    private String name;&lt;br&gt;    private String author;&lt;br&gt;    private Float price;&lt;br&gt;\\}&lt;br&gt;</code></td></tr></tbody></table><p>（2）接着在 <strong>hangge-dao</strong> 模块中添加 <strong>BookDao</strong> 接口，继承 <strong>JpaRepository</strong>：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;</code></td><td><code>&lt;br&gt;public interface BookDao extends JpaRepository\\&lt;Book, Integer\\&gt; \\{&lt;br&gt;\\}&lt;br&gt;</code></td></tr></tbody></table><p>（3）接着在 <strong>hangge-service</strong> 模块中添加一个业务实现类 <strong>BookService</strong>，注入 <strong>BookDao</strong> 并调用：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;</code></td><td><code>&lt;br&gt;@Service&lt;br&gt;public class BookService \\{&lt;br&gt;    @Autowired&lt;br&gt;    BookDao bookDao;&lt;br&gt; &lt;br&gt;    public List\\&lt;Book\\&gt; allBooks() \\{&lt;br&gt;        return bookDao.findAll();&lt;br&gt;    \\}&lt;br&gt;\\}&lt;br&gt;</code></td></tr></tbody></table><p>（4）然后在 <strong>hangge-web</strong> 模块中创建一个 <strong>Controller</strong>，注入 <strong>BookService</strong> 并调用：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;</code></td><td><code>&lt;br&gt;@RestController&lt;br&gt;public class HelloController \\{&lt;br&gt; &lt;br&gt;    @Autowired&lt;br&gt;    BookService bookService;&lt;br&gt; &lt;br&gt;    @GetMapping(&quot;test&quot;)&lt;br&gt;    public List\\&lt;Book\\&gt; test() \\{&lt;br&gt;        return bookService.allBooks();&lt;br&gt;    \\}&lt;br&gt;\\}&lt;br&gt;</code></td></tr></tbody></table><p>（5）最后在 <strong>hangge-web</strong> 模块的 <strong>application.properties</strong> 中配置数据库基本信息以及 <strong>JPA</strong> 相关配置： ==spring.datasource.type=========com====.====alibaba====.====druid====.====pool====.====DruidDataSource== ==spring.datasource.url=========jdbc:mysql://localhost:3306/hangge2====?serverTimezone=Asia/Shanghai== ==spring.datasource.username=========root== ==spring.datasource.password=========hangge1234== ==#====是否在控制台打印====JPA====执行过程生成的====SQL== ==spring.jpa.show-sql=========true== ==#====表示====JPA====对应的数据库是====MySQL== ==spring.jpa.database=======<em>mysql</em> ==#====表示在项目启动时根据实体类更新数据库中的表== ==spring.jpa.hibernate.ddl-auto=========update== ==#====表示使用的数据库方言是====MySQL57Dialect== ==spring.jpa.properties.hibernate.dialect=========org.hibernate.dialect.MySQL57Dialect== <strong>7，运行测试</strong> （1）运行 <strong>hangge-web</strong> 模块下的 <strong>Application</strong> 的启动类：</p><p><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a></p><p>（2）使用浏览器访问 <strong><a href="http://localhost:8080/test" target="_blank" rel="noreferrer">http://localhost:8080/test</a></strong> 便可查询到相关的数据信息：</p><p><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a></p><p>原文出自：<a href="https://www.hangge.com/" target="_blank" rel="noreferrer">www.hangge.com</a>  转载请保留原文链接： <a href="https://www.hangge.com/blog/cache/detail_2833.html" target="_blank" rel="noreferrer">https://www.hangge.com/blog/cache/detail_2833.html</a></p><p><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2833.html#" target="_blank" rel="noreferrer"></a></p></div>',1)])])}const h=r(o,[["render",b]]);export{i as __pageData,h as default};
